targets.query:
from(bucket: "TEST")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "alert_data")
  |> filter(fn: (r) => r._field == "status")
  |> last()
  |> map(fn: (r) => ({
      Status_Listrik: r._value
  }))

from(bucket: "TEST")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "alert_data")
  |> filter(fn: (r) => r._field == "battery_percent")
  |> last()
  |> map(fn: (r) => ({
      Sisa_Baterai: r._value
  }))

from(bucket: "TEST")
  |> range(start: -30d)
  |> filter(fn: (r) => r._measurement == "alert_data")
  |> filter(fn: (r) => r._field == "power_status")
  |> filter(fn: (r) => r._value == 0)
  |> last()
  |> map(fn: (r) => ({
      _value: uint(v: r._time) / uint(v: 1000000),
      _field: "Terakhir Padam"
  }))
